contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= v);

        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeC = address(c).balance;
        uint beforeSelf = address(this).balance;

        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterC = address(c).balance;
        uint afterSelf = address(this).balance;

        assert(
            reverted
                ? (afterDeposits == beforeDeposits && afterC == beforeC && afterSelf == beforeSelf)
                : (afterDeposits == beforeDeposits && afterC + v == beforeC && afterSelf == beforeSelf + v)
        );
    }

    receive() external payable {}
}

