pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= v);
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeC = address(c).balance;
        uint beforeSelf = address(this).balance;
        bool reverted;
        try c.withdraw(v) { reverted = false; } catch { reverted = true; }
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        uint afterC = address(c).balance;
        uint afterSelf = address(this).balance;
        assertTrue(reverted
                ? (afterDeposits == beforeDeposits && afterC == beforeC && afterSelf == beforeSelf)
                : (afterDeposits == beforeDeposits && afterC + v == beforeC && afterSelf == beforeSelf + v));
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
